export type TableQueryDto = {
	target: TableTarget,
	columns: string[],
	filters: FilterDto[],
	combinator: CombinatorDto,
	sort: SortDto | null,
	/**
	 *  A keyless `SQLite` table's rowid alias (`EditInfoDto::row_id`),
	 *  selected as the last column for row identity and never shown.
	 */
	rowId?: string | null,
};

/**  Columns, indexes and the planner row estimate of a relation. */
export type TableStructureDto = {
	columns: TableColumnDto[],
	indexes: TableIndexDto[],
	rowEstimate: number | null,
};

/**  The browsed relation on a saved connection's database. */
export type TableTarget = {
	profileId: string,
	database: string,
	schema: string,
	table: string,
};

/**
 *  The outcome of Test connection: every step that ran, the server on
 *  success, the typed error of the failing step otherwise.
 */
export type TestReport = {
	steps: TestStepDto[],
	server: ServerDto | null,
	error: IpcError | null,
	/**  The server certificate, when TLS was negotiated. */
	certificate: CertificateDto | null,
	/**  Round trips of `SELECT 1` after connecting. */
	latency: LatencyDto | null,
	elapsedMs: number,
};

/**  One line of the Test connection report. */
export type TestStepDto = {
	kind: TestStepKind,
	label: string,
	status: StepStatus,
	detail: string | null,
	/**  What to change when the step failed. */
	hint: string | null,
	elapsedMs: number | null,
};

/**  What a step checks. */
export type TestStepKind = 
/**  Resolve and reach an SSH server (or the next jump host). */
"sshConnect" | 
/**  SSH handshake, host key and authentication. */
"sshAuth" | 
/**  Open the tunnel stream to the database. */
"tunnel" | 
/**  Resolve the database host name (direct connections). */
"dns" | 
/**  TCP connect (or Unix socket) to the database. */
"connect" | 
/**  TLS negotiation and handshake. */
"tls" | 
/**  Database authentication. */
"authenticate" | 
/**  Server product and version. */
"version" | 
/**  Round trip of a trivial query. */
"latency";

export type TileTiming = {
	rowStart: number,
	invokeMs: number | null,
	decodeMs: number | null,
	workerDecodeMs: number | null,
	totalMs: number | null,
};

/**  Saved TLS certificate files and whether verification is skipped. */
export type TlsFilesDto = {
	caFile: string | null,
	/**  A bundled cloud provider CA instead of a CA file. */
	cloudCa: CloudCaDto | null,
	clientCert: string | null,
	clientKey: string | null,
	hasKeyPassphrase: boolean,
	/**
	 *  The server certificate of a remote host is not authenticated: show
	 *  the skip-verification warning.
	 */
	unverifiedRemote: boolean,
};

/**  TLS certificate files from the form. */
export type TlsFilesInput = {
	caFile: string | null,
	/**  Absent in forms written before cloud CAs: none. */
	cloudCa?: CloudCaDto | null,
	clientCert: string | null,
	clientKey: string | null,
	keyPassphrase: SecretInput,
};

/**  libpq `sslmode` values (docs/12 §4.1). */
export type TlsModeDto = "disable" | "allow" | "prefer" | "require" | "verify-ca" | "verify-full";

/**  One trigger in the Triggers sheet. */
export type TriggerDto = {
	name: string,
	timing: TriggerTimingDto,
	/**  `INSERT`, `UPDATE`, `DELETE`, `TRUNCATE`. */
	events: string[],
	rowLevel: boolean,
	function: string,
	enabled: boolean,
	definition: string,
};

/**  When a trigger fires. */
export type TriggerTimingDto = "before" | "after" | "insteadOf";

/**
 *  One webview report. `name` is the error name or the command; `message`
 *  is free text and is scrubbed and clipped before it is written.
 */
export type UiReport = {
	kind: UiReportKind,
	name: string,
	message: string | null,
	durationMs: number | null,
};

/**  What the webview reports: an error, a rejected promise, or a timing. */
export type UiReportKind = "error" | "unhandledRejection" | "longTask" | "slowIpc";

/**  Form fields filled from a pasted URL; only says whether it had a password. */
export type UrlDraft = {
	engine: EngineDto,
	file: FileDto | null,
	host: string,
	port: number,
	database: string | null,
	user: string | null,
	tlsMode: TlsModeDto,
	passwordProvided: boolean,
};

/**  The safety gate's decision for one statement. */
export type VerdictDto = "allow" | "confirm" | "block";

export type WindowRequest = {
	resultId: string,
	rowStart: number,
	rowCount: number,
	colStart: number,
	colCount: number,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

